# owner: platform
import unittest

from hourglass.errors import OutsideHoursError
from hourglass.gaps import gap_labels
from hourglass.models import Span

OPEN = Span(8 * 60, 18 * 60)


class GapLabelTests(unittest.TestCase):
    def test_no_one_working_is_one_big_gap(self):
        self.assertEqual(gap_labels([], OPEN), ["gap 08:00-18:00 (600 min)"])

    def test_gap_between_spans(self):
        worked = [Span(8 * 60, 12 * 60), Span(13 * 60, 18 * 60)]
        self.assertEqual(gap_labels(worked, OPEN), ["gap 12:00-13:00 (60 min)"])

    def test_gaps_at_both_ends(self):
        worked = [Span(9 * 60, 17 * 60)]
        self.assertEqual(
            gap_labels(worked, OPEN),
            ["gap 08:00-09:00 (60 min)", "gap 17:00-18:00 (60 min)"]
        )

    def test_overlapping_and_touching_spans_leave_no_gap(self):
        worked = [Span(600, 800), Span(480, 620), Span(800, 1080)]
        self.assertEqual(gap_labels(worked, OPEN), [])

    def test_unsorted_input(self):
        worked = [Span(15 * 60, 18 * 60), Span(8 * 60, 10 * 60)]
        self.assertEqual(gap_labels(worked, OPEN), ["gap 10:00-15:00 (300 min)"])

    def test_accepts_any_iterable(self):
        worked = iter([Span(8 * 60, 18 * 60)])
        self.assertEqual(gap_labels(worked, OPEN), [])


class OutsideHoursTests(unittest.TestCase):
    def test_starts_too_early(self):
        with self.assertRaises(OutsideHoursError):
            gap_labels([Span(7 * 60, 10 * 60)], OPEN)

    def test_ends_too_late(self):
        with self.assertRaises(OutsideHoursError):
            gap_labels([Span(9 * 60, 19 * 60)], OPEN)

    def test_error_is_a_value_error(self):
        with self.assertRaises(ValueError):
            gap_labels([Span(0, 60)], OPEN)
